use super::*;

/// The category a description falls in, or NONE — which is not the same as "other".
pub fn categorise(description: &str) -> Option<&'static str> {
    let text = description.to_lowercase();
    CATEGORY_RULES.iter().find(|(_, matches)| matches.iter().any(|m| text.contains(m))).map(|(c, _)| *c)
}
